//! 📥️ Original host admission measures borrowed JSON before physical input reservation.
use semio_framework_value::{ValueError, ValueRefusalKind};
#[path="🛫️encode/🦀️.rs"]
mod encoding;

pub(super) struct JsonInputWriter<'control,'observer,'output>{pub(super) control:&'control mut semio_framework_value::NativeEncodeControl<'observer>,pub(super) output:Option<&'output mut Vec<u8>>,pub(super) count:usize}
impl JsonInputWriter<'_,'_,'_>{
 pub(super) fn native_write(&mut self,bytes:&[u8])->Result<(),ValueError>{let count=self.count.checked_add(bytes.len()).filter(|count|*count<=isize::MAX as usize).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"owned input JSON length exceeds address space"))?;if self.output.as_ref().is_some_and(|output|output.len().checked_add(bytes.len()).is_none_or(|next|next>output.capacity())){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"owned input changed after its measured reservation"));}self.control.advance(bytes.len())?;if let Some(output)=self.output.as_mut(){output.extend_from_slice(bytes);}self.count=count;Ok(())}
}
pub(super) struct JsonBackingOwner{pub(super) bytes:std::mem::ManuallyDrop<Option<Vec<u8>>>}
impl semio_framework_value::ErasedSnapshotRetirement for JsonBackingOwner{
    fn close_step(&mut self,grant:semio_framework_value::retained_clone::RetainedCloneGrant)->Result<semio_framework_value::retained_clone::RetainedCloneStep,ValueError>{use semio_framework_value::retained_clone::{RetainedCloneStep,RetainedCloneProgress};let empty=RetainedCloneProgress::default();if self.bytes.is_none(){return Ok(RetainedCloneStep::Complete(empty));}let release=self.bytes.as_ref().unwrap().capacity();let copy=std::mem::size_of::<Option<Vec<u8>>>();if grant.maximum_items==0||grant.maximum_copy_bytes<copy||grant.maximum_release_bytes<release{return Ok(RetainedCloneStep::Progress(empty));}if grant.maximum_depth==0{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"host JSON release requires original depth"));}drop(self.bytes.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:copy,released_bytes:release,..empty}))}
    fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(if self.bytes.is_some(){std::mem::size_of::<Option<Vec<u8>>>()}else{0})}
    fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
    fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.bytes.as_ref().map_or(0,Vec::capacity))}
    fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(usize::from(self.bytes.is_some()))}
    fn terminal_is_empty(&self)->bool{self.bytes.is_none()}
}
impl Drop for JsonBackingOwner{fn drop(&mut self){assert!(std::thread::panicking()||self.bytes.is_none(),"host JSON original frame reached Drop before admitted release");if self.bytes.is_none(){unsafe{std::mem::ManuallyDrop::drop(&mut self.bytes);}}}}

pub(super) fn encode_borrowed<I:serde::Serialize>(writer:&mut JsonInputWriter<'_ ,'_ ,'_>,input:&I)->Result<(),ValueError>{encoding::write(writer,input)}

/// 📥️ Measures borrowed input before the original caller admits its exact physical reservation.
pub(crate) fn encode_json_input<I:serde::Serialize>(input:&I,control:&mut semio_framework_value::NativeEncodeControl<'_>)->Result<Vec<u8>,ValueError>{
    control.scoped_stage(|control|{control.begin_stage(0)?;let mut measure=JsonInputWriter{control,output:None,count:0};encode_borrowed(&mut measure,input)?;let count=measure.count;control.begin_stage(count)?;control.with_retirement_owner(std::mem::size_of::<JsonBackingOwner>(),|control|{let mut owner=Box::new(JsonBackingOwner{bytes:std::mem::ManuallyDrop::new(None)});let result=(||{owner.bytes.replace(control.allocate_vec(count)?);let mut writer=JsonInputWriter{control,output:owner.bytes.as_mut(),count:0};encode_borrowed(&mut writer,input)?;if writer.count!=count{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"owned input changed after measurement"));}Ok(owner.bytes.take().unwrap())})();(result,Some(owner as Box<dyn semio_framework_value::ErasedSnapshotRetirement>))})})
}


/// 🫴️ Publishes the real input backing to its caller before serialization can be cancelled.
pub(crate) fn encode_json_input_into<I:serde::Serialize>(input:&I,control:&mut semio_framework_value::NativeEncodeControl<'_>,output:&mut Option<Vec<u8>>)->Result<(),ValueError>{
 if output.is_some(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"owned input backing is already retained"));}
 control.scoped_stage(|control|{control.begin_stage(0)?;let mut measure=JsonInputWriter{control,output:None,count:0};encode_borrowed(&mut measure,input)?;let count=measure.count;control.begin_stage(count)?;*output=Some(control.allocate_vec(count)?);let mut writer=JsonInputWriter{control,output:output.as_mut(),count:0};encode_borrowed(&mut writer,input)?;if writer.count!=count{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"owned input changed after measurement"));}Ok(())})
}

#[cfg(test)]
mod tests {
 use super::*;
 use semio_framework_value::{retirement::controlled::ControlledRetirement,RetainedCloneGrant};
 #[test]
 fn original_owned_json_refusal_returns_actual_partial_buffer_to_original_recipient(){
  let law:serde_json::Value=serde_json::from_str(include_str!("../../../../🧬️schema/🪶️sqlite/🧫️fixtures/📥️input/🔣️.json")).unwrap();let policy:serde_json::Value=serde_json::from_str(include_str!("🛫️encode/🧫️fixtures/🔣️.json")).unwrap();let maximum=policy["maximumBytes"].as_u64().unwrap()as usize;let live=std::cell::Cell::new(false);let threshold=law["cancelAfterCompleted"].as_u64().unwrap()as usize;let mut observer=|progress:semio_framework_value::native_encoding::NativeEncodeProgress|live.get()||progress.owned_bytes==0||progress.completed<threshold;let mut original=semio_framework_value::native_encoding::NativeEncodeRetirementRecipient::new();let mut control=semio_framework_value::NativeEncodeControl::new(maximum,&mut observer);control.install_retirement_recipient(&mut original).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||encode_json_input(&law["input"],&mut control));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(heap.released_bytes,0);assert_eq!(heap.requested_bytes,control.owned_bytes());assert!(control.has_retirement_owner());live.set(true);let p=&policy["grant"];let grant=RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap()as usize};let mut released=0;while control.has_retirement_owner(){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||control.close_retirement_recipient(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),(heap.requested_bytes,heap.released_bytes));released+=heap.released_bytes;}assert!(released>=law["canonical"].as_str().unwrap().len());drop(control);assert!(!original.has_owner());println!("[DEBUG] actual returned-Vec cancellation retains original input backing until same recipient and independent caller grant admit physical close");
 }
 fn close_original(bytes:Vec<u8>,policy:&serde_json::Value){let mut owner=ControlledRetirement::new(bytes).unwrap_or_else(|_|panic!("original parity output requires retirement"));let grant=RetainedCloneGrant{maximum_items:policy["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:policy["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:policy["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:policy["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:policy["maximumDepth"].as_u64().unwrap()as usize};while !owner.terminal_is_empty(){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),(heap.requested_bytes,heap.released_bytes));}let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 #[test]
 fn original_json_scalar_writer_matches_independent_serde_and_cancels_without_error_backing(){
  let law:serde_json::Value=serde_json::from_str(include_str!("🛫️encode/🧫️fixtures/🔣️.json")).unwrap();let maximum=law["maximumBytes"].as_u64().unwrap()as usize;
  for source in law["values"].as_array().unwrap(){let expected=serde_json::to_vec(source).unwrap();let events=std::cell::Cell::new(0);let mut observer=|_:semio_framework_value::native_encoding::NativeEncodeProgress|{events.set(events.get()+1);true};let mut control=semio_framework_value::NativeEncodeControl::new(maximum,&mut observer);let mut output=None;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||encode_json_input_into(source,&mut control,&mut output));result.unwrap();assert_eq!(output.as_ref().unwrap(),&expected);assert_eq!(heap.requested_bytes,expected.len());assert_eq!(heap.released_bytes,0);let count=events.get();close_original(output.take().unwrap(),&law["grant"]);
   for denied in 1..=count{let seen=std::cell::Cell::new(0);let mut observer=|_:semio_framework_value::native_encoding::NativeEncodeProgress|{seen.set(seen.get()+1);seen.get()!=denied};let mut control=semio_framework_value::NativeEncodeControl::new(maximum,&mut observer);let mut output=None;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||encode_json_input_into(source,&mut control,&mut output));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(heap.released_bytes,0);assert_eq!(heap.requested_bytes,output.as_ref().map_or(0,Vec::capacity));assert_eq!(control.owned_bytes(),heap.requested_bytes);if let Some(output)=output.take(){close_original(output,&law["grant"]);}}
  }
  for value in law["float32"].as_array().unwrap(){let source=value.as_f64().unwrap()as f32;let expected=serde_json::to_vec(&source).unwrap();let mut observer=|_:semio_framework_value::native_encoding::NativeEncodeProgress|true;let mut control=semio_framework_value::NativeEncodeControl::new(maximum,&mut observer);let mut output=None;encode_json_input_into(&source,&mut control,&mut output).unwrap();assert_eq!(output.as_ref().unwrap(),&expected);close_original(output.take().unwrap(),&law["grant"]);}
  for bits in law["float32Bits"].as_array().unwrap(){let source=f32::from_bits(bits.as_u64().unwrap()as u32);let expected=serde_json::to_vec(&source).unwrap();let mut observer=|_:semio_framework_value::native_encoding::NativeEncodeProgress|true;let mut control=semio_framework_value::NativeEncodeControl::new(maximum,&mut observer);let mut output=None;encode_json_input_into(&source,&mut control,&mut output).unwrap();assert_eq!(output.as_ref().unwrap(),&expected);close_original(output.take().unwrap(),&law["grant"]);}
  println!("[DEBUG] original scalar JSON null/bool/int/float/UTF8/list/map byte parity and every observed callback refusal preserve actual backing without error allocation");
 }
 #[test]
 fn original_snapshot_input_cancellation_retains_actual_json_backing(){
  let law:serde_json::Value=serde_json::from_str(include_str!("../../../../🧬️schema/🪶️sqlite/🧫️fixtures/📥️input/🔣️.json")).unwrap();let canonical=serde_json::to_vec(&law["input"]).unwrap();assert_eq!(canonical,law["canonical"].as_str().unwrap().as_bytes());let maximum=law["nativeMaximumBytes"].as_u64().unwrap()as usize;let threshold=law["cancelAfterCompleted"].as_u64().unwrap()as usize;let mut observer=|progress:semio_framework_value::native_encoding::NativeEncodeProgress|progress.owned_bytes==0||progress.completed<threshold;let mut control=semio_framework_value::NativeEncodeControl::new(maximum,&mut observer);let mut output=None;
  let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||encode_json_input_into(&law["input"],&mut control,&mut output));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);let bytes=output.as_ref().unwrap();assert_eq!(bytes.as_slice(),law["partialPrefix"].as_str().unwrap().as_bytes());assert_eq!(bytes.capacity(),canonical.len());assert_eq!(heap.requested_bytes,bytes.capacity());assert_eq!(heap.released_bytes,law["deniedReleaseBytes"].as_u64().unwrap()as usize);assert_eq!(control.owned_bytes(),bytes.capacity());assert_eq!(control.maximum_bytes(),maximum);
  let mut owner=ControlledRetirement::new(output.take().unwrap()).unwrap_or_else(|_|panic!("authored snapshot input retirement failed"));let denied=RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(denied));assert_eq!(step.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(owner.original().unwrap().capacity(),canonical.len());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:32};let mut release=0;let mut turns=0;
  while !owner.terminal_is_empty(){let demand=owner.next_capacity_byte_demand(grant.maximum_copy_bytes).unwrap();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||control.scoped_stage(|control|{control.begin_stage(0)?;control.charge(demand)?;owner.step(grant)}));let progress=step.unwrap().progress();assert!(progress.fits(grant));assert_eq!(heap.requested_bytes,progress.retained_capacity_bytes);assert_eq!(demand,heap.requested_bytes);assert_eq!(heap.released_bytes,progress.released_bytes);release+=heap.released_bytes;turns+=1;assert!(turns<128);}
  assert!(release>=canonical.len());assert_eq!(control.maximum_bytes(),maximum);assert!(control.owned_bytes()>=canonical.len());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] actual cancelled input retains prefix12 capacity{} with denied release0, measured admitted retirement release{}",canonical.len(),release);
 }
}
